  courseId: number;
  lessonId: number;
  allCourses: Course[]; // Этот пропс больше не нужен, но оставим для совместимости
  onClose: () => void;
  onComplete: (courseId: number) => void;
}> = ({courseId, lessonId, allCourses, onClose, onComplete}) => {
  const [answers, setAnswers] = useState<Record<string, string | string[]>>({});
  const [isSubmitted, setIsSubmitted] = useState(false);
  const [testResult, setTestResult] = useState<'passed' | 'failed' | null>(null);
  const [score, setScore] = useState(0);
  const [showResultModal, setShowResultModal] = useState(false);
  const [showCourseCompleteModal, setShowCourseCompleteModal] = useState(false);

  // Новые состояния для загрузки данных
  const [course, setCourse] = useState<Course | null>(null);
  const [loading, setLoading] = useState(true);

  // Загружаем полные данные о курсе самостоятельно
  useEffect(() => {
    const loadCourse = async () => {
      setLoading(true);
      try {
        const data = await fetchCourseById(courseId);
        setCourse(data);
      } catch (error) {
        console.error("Failed to load course for lesson page:", error);
        setCourse(null);
      } finally {
        setLoading(false);
      }
    };

    loadCourse();
  }, [courseId]);

  const lesson = useMemo(() => {
    if (!course || !course.program || course.program.length === 0) {
      return null;
    }
    return course.program.find(l => l.id === lessonId);
  }, [course, lessonId]);

  const lessonIndex = useMemo(() => {
    if (!course || !course.program || !lesson) return -1;
    return course.program.findIndex(l => l.id === lessonId);
  }, [course, lesson, lessonId]);

  const handleAnswerChange = (questionId: string, answer: string) => {
    if (!lesson?.quiz) return;
    const question = lesson.quiz.find(q => q.id === questionId);
    if (!question) return;

    if (question.type === 'single') {
      setAnswers(prev => ({...prev, [questionId]: answer}));
    } else {
      const currentAnswers = (answers[questionId] as string[] | undefined) || [];
      const newAnswers = currentAnswers.includes(answer)
        ? currentAnswers.filter(a => a !== answer)
        : [...currentAnswers, answer];
      setAnswers(prev => ({...prev, [questionId]: newAnswers}));
    }
  };

  const handleSubmitTest = async () => {
    if (!lesson?.quiz || !course) return;

    // Локальная проверка для отображения результатов
    let correctAnswers = 0;
    lesson.quiz.forEach(q => {
      const userAnswer = answers[q.id];
      if (q.type === 'single' && userAnswer === q.correctAnswer) {
        correctAnswers++;
      } else if (q.type === 'multiple') {
        const userAnswersSet = new Set(userAnswer as string[]);
        const correctAnswersSet = new Set(q.correctAnswers);
        if (userAnswersSet.size === correctAnswersSet.size && [...userAnswersSet].every(a => correctAnswersSet.has(a))) {
          correctAnswers++;
        }
      }
    });

    const newScore = correctAnswers;
    setScore(newScore);
    setIsSubmitted(true);

    const passed = newScore / lesson.quiz.length >= COURSE_PASS_THRESHOLD;
    setTestResult(passed ? 'passed' : 'failed');
    setShowResultModal(true);

    // Если тест пройден и это последний урок, отправляем данные на бэкенд
    if (passed && course.program && lessonIndex === course.program.length - 1) {
      try {
        // Формируем массив ответов для бэкенда (только для текущего теста)
        const backendAnswers: { questionId: number; answerId: number }[] = [];

        if (lesson.quiz) {
          for (const question of lesson.quiz) {
            const questionId = parseInt(question.id);

            // Находим выбранные пользователем ответы
            const userAnswer = answers[question.id];

            if (question.type === 'single' && typeof userAnswer === 'string') {
              // Для single-choice находим ID ответа
              const answerId = question.answerIds?.[userAnswer];
              if (answerId) {
                backendAnswers.push({
                  questionId,
                  answerId,
                });
              }
            } else if (question.type === 'multiple' && Array.isArray(userAnswer)) {
              // Для multiple-choice добавляем все выбранные ответы
              for (const answer of userAnswer) {
                const answerId = question.answerIds?.[answer];
                if (answerId) {
                  backendAnswers.push({
                    questionId,
                    answerId,
                  });
                }
              }
            }
          }
        }

        // Отправляем на бэкенд
        await completeCourse(courseId, backendAnswers);

        setTimeout(() => {
          setShowResultModal(false);
          setShowCourseCompleteModal(true);
        }, 1500);
      } catch (error) {
        console.error('Failed to complete course on backend:', error);
        // Все равно показываем модалку, но без сертификата с бэкенда
        setTimeout(() => {
          setShowResultModal(false);
          setShowCourseCompleteModal(true);
        }, 1500);
      }
    }
  };

  const handleTryAgain = () => {
    setAnswers({});
    setIsSubmitted(false);
    setTestResult(null);
    setScore(0);
    setShowResultModal(false);
  };

  const handleContinue = () => {
    if (course && course.program && lessonIndex === course.program.length - 1) {
      setShowCourseCompleteModal(true);
    } else {
      onClose();
    }
  };

  if (loading) {
    return <div className="w-full h-screen flex items-center justify-center">Загрузка...</div>;
  }

  if (!course || !lesson) {
    return <div className="w-full h-screen flex items-center justify-center">Урок не найден.</div>;
  }

  const isTest = lesson.type === 'test';
  const totalQuestions = lesson.quiz?.length || 0;
  const allQuestionsAnswered = isTest && lesson.quiz?.every(q => answers[q.id] && (answers[q.id] as any[]).length > 0);

  return (
    <>
      <div className="w-full h-screen font-sans antialiased bg-white flex flex-col">
        <header className="flex-shrink-0 p-4 border-b border-gray-200 flex items-center justify-between">
          <div className="flex items-center space-x-2">
            <div className="w-8 h-8 rounded-lg flex items-center justify-center bg-blue-100">
              {isTest ? <Puzzle className="w-5 h-5 text-[#007AFF]"/> : <Check className="w-5 h-5 text-[#007AFF]"/>}
            </div>
            <div>
              <p className="text-sm text-gray-500">{course.title}</p>
              <h1 className="text-lg font-bold text-[#0C0D0E]">{lesson.title}</h1>
            </div>
          </div>
          <button onClick={onClose}
                  className="w-10 h-10 flex items-center justify-center rounded-full hover:bg-gray-100"
                  aria-label="Закрыть">
            <X className="w-6 h-6 text-gray-700"/>
          </button>
        </header>

        <div className="w-full h-1 bg-gray-200">
          <div className="h-1 bg-[#007AFF]"
               style={{width: `${course.program ? ((lessonIndex + 1) / course.program.length) * 100 : 0}%`}}></div>
        </div>

        <main className="flex-grow overflow-y-auto p-6 space-y-6">
          {isTest ? (
            <div className="space-y-6">
              <h2 className="text-2xl font-bold">{lesson.contentTitle}</h2>
              <div className="prose max-w-none text-gray-600 leading-relaxed">
                {renderMarkdown(lesson.content)}
              </div>
              {lesson.quiz?.map((q, index) => (
                <div key={q.id} className="border-t border-gray-200 pt-4">
                  <p className="font-semibold">{`${index + 1}. ${q.question}`}</p>
                  <div className="mt-2 space-y-2">
                    {q.options.map(opt => (
                      <label key={opt} className={`flex items-center space-x-3 p-3 rounded-lg border-2 ${
                        isSubmitted
                          ? (q.correctAnswer === opt || q.correctAnswers?.includes(opt)) ? 'border-green-400 bg-green-50' : ((answers[q.id] === opt || (answers[q.id] as string[])?.includes(opt))) ? 'border-red-400 bg-red-50' : 'border-gray-200'
                          : 'border-gray-200'
                      }`}>
                        <input
                          type={q.type === 'single' ? 'radio' : 'checkbox'}
                          name={q.id}
                          value={opt}
                          checked={q.type === 'single' ? answers[q.id] === opt : (answers[q.id] as string[] | undefined)?.includes(opt)}
                          onChange={() => handleAnswerChange(q.id, opt)}
                          disabled={isSubmitted}
                          className="w-5 h-5"
                        />
                        <span>{opt}</span>
                      </label>
                    ))}
                  </div>
                </div>
              ))}
            </div>
          ) : (
            <div className="prose max-w-none">
              <h2>{lesson.contentTitle}</h2>
              {renderMarkdown(lesson.content)}
            </div>
          )}
        </main>

        <footer className="flex-shrink-0 p-4 bg-white/80 backdrop-blur-sm border-t border-gray-100">
          <button
            onClick={isTest ? handleSubmitTest : handleContinue}
            disabled={isTest && !allQuestionsAnswered}
            className="w-full text-white font-bold py-4 px-4 rounded-xl transition-all duration-300 flex items-center justify-center shadow-lg bg-[linear-gradient(157deg,#08D7F3_6.38%,#5398FF_85%)] hover:opacity-90 disabled:bg-gray-300 disabled:cursor-not-allowed"
          >
            {isTest ? 'Проверить ответы' : 'Завершить урок'}
          </button>
        </footer>
      </div>
      <TestResultModal
        isOpen={showResultModal}
        result={testResult}
        score={score}
        totalQuestions={totalQuestions}
        onTryAgain={handleTryAgain}
        onBackToLesson={() => setShowResultModal(false)}
        onViewCertificate={() => onComplete(courseId)}
      />
      <CourseCompleteModal
        isOpen={showCourseCompleteModal}
        courseTitle={course.title}
        onClose={() => {
          setShowCourseCompleteModal(false);
          onClose();
        }}
        onViewCertificate={() => onComplete(courseId)}
      />
    </>
  );
};
export default LessonPage;

import {supabase} from './auth.real';
import type {
  Achievement,
  AppEvent,
  Course,
  EventChatMessage,
  EventParticipant,
  Friend,
  HistoryEvent,
  LeaderboardUser,
  MapMarker,
  MyChatItem,
  Organization,
  OrganizationDetails,
  OrganizationEvent,
  OrganizationStat,
  RewardItem,
  Story,
  WeeklyChallenge
} from './types';
import {BookOpen, Clock, Dog, GraduationCap, HandHeart, Leaf, List, Palette, Star, Trophy, Users} from 'lucide-react';
import React from 'react';

const API_BASE_URL = import.meta.env.VITE_API_BASE_URL;

const iconMap: { [key: string]: React.FC<any> } = {
  'hand-heart': HandHeart,
  'dog': Dog,
  'leaf': Leaf,
  'users': Users,
  'palette': Palette,
  'trophy': Trophy,
  'clock': Clock,
  'star': Star,
  'graduation-cap': GraduationCap,
  'list': List,
  'default': Star,
};

const getIcon = (iconName?: string | null): React.FC<any> => {
  if (!iconName) return iconMap['default'];
  return iconMap[iconName] || iconMap['default'];
};

const categoryIconMap: { [key: string]: React.FC<any> } = {
  'Экология': Leaf,
  'Животные': Dog,
  'Помощь старшим': HandHeart,
  'Арт': Palette,
  'Онлайн': BookOpen,
  'Спорт': Trophy,
  'Культура': Palette,
  'Дети': Users,
  'default': Star,
};

const getIconForCategory = (category?: string | null): React.FC<any> => {
  if (!category) return categoryIconMap['default'];
  return categoryIconMap[category] || categoryIconMap['default'];
};

const getAuthToken = async (): Promise<string | null> => {
  const internalToken = localStorage.getItem('internal_jwt');
  if (internalToken) {
    return internalToken;
  }

  if (!supabase) return null;
  const { data } = await supabase.auth.getSession();
  return data.session?.access_token || null;
};

async function apiFetch<T>(endpoint: string, options: RequestInit = {}): Promise<T> {
  const token = await getAuthToken();
  const authHeaders: Record<string, string> = {};
  if (token) {
    authHeaders['Authorization'] = `Bearer ${token}`;
  }

  const response = await fetch(`${API_BASE_URL}${endpoint}`, {
    ...options,
    headers: {
      'Content-Type': 'application/json',
      ...authHeaders,
      ...options.headers,
    },
  });

  if (!response.ok) {
    const errorData = await response.json().catch(() => ({message: 'Server error'}));
    throw new Error(errorData.message || 'Something went wrong');
  }

  return response.json();
}

// Helper for mapping icon property
const mapIcon = <T extends { icon?: string | null }>(item: T): Omit<T, 'icon'> & { Icon: React.FC<any> } => {
  const {icon, ...rest} = item;
  return {...rest, Icon: getIcon(icon)};
};

const mapEventData = (event: any): AppEvent => ({
  ...event,
  Icon: getIconForCategory(event.category),
  participantCount: event._count?.participants ?? 0,
  organizationName: event.organization?.name ?? 'Организация', // Placeholder
  pos: {top: '0', left: '0'}, // Dummy value, not used
});

export const fetchAllEvents = async (): Promise<AppEvent[]> => {
  const events = await apiFetch<any[]>('/events');
  return events.map(mapEventData);
};

export const fetchEventById = async (id: number): Promise<AppEvent | HistoryEvent> => {
  const event = await apiFetch<any>(`/events/${id}`);
  return mapEventData(event);
};

const mapCourseData = (courseData: any): Course => {
  const mappedProgram = (courseData.lessons || []).map((lesson: any, index: number) => {
    const lessonType = (lesson.questions && lesson.questions.length > 0) ? 'test' : 'lesson';

    // TODO: Временная логика для статуса. В идеале, это должно приходить с бэкенда.
    const lessonStatus = index === 0 ? 'current' : 'locked';

    const mappedQuiz = (lesson.questions || []).map((q: any) => {
      // Находим правильные ответы (предполагаем, что в БД есть поле isCorrect)
      const correctAnswers = q.answers
        .filter((a: any) => a.isCorrect)
        .map((a: any) => a.answer);

      return {
        id: q.id.toString(),
        question: q.question,
        type: correctAnswers.length > 1 ? 'multiple' : 'single',
        options: q.answers.map((a: any) => a.answer),
        correctAnswer: correctAnswers.length === 1 ? correctAnswers[0] : undefined,
        correctAnswers: correctAnswers.length > 1 ? correctAnswers : undefined,
      };
    });

    return {
      id: lesson.id,
      title: lesson.title,
      type: lessonType,
      status: lessonStatus,
      contentTitle: lesson.title,
      content: lesson.content,
      quiz: mappedQuiz.length > 0 ? mappedQuiz : undefined,
    };
  });

  return {
    ...mapIcon(courseData), // Используем существующий маппер для иконки
    id: courseData.id,
    title: courseData.title,
    description: courseData.description,
    duration: courseData.duration || "N/A", // Добавляем запасные значения
    hasCertificate: courseData.hasCertificate || false,
    category: courseData.category || "General",
    status: courseData.status || 'not-started',
    progress: courseData.progress || 0,
    level: courseData.level || 'Для новичков',
    program: mappedProgram.length > 0 ? mappedProgram : [], // Гарантируем, что program всегда массив
  };
};

export const fetchAllCourses = async (): Promise<Course[]> => {
  const coursesData = await apiFetch<any[]>('/courses');
  return coursesData.map(mapCourseData);
};

export const fetchCourseById = async (id: number): Promise<Course> => {
  const rawCourseData = await apiFetch<any>(`/courses/${id}`);
  return mapCourseData(rawCourseData);
};

export const fetchAllOrganizations = (): Promise<Organization[]> => apiFetch('/organizations');
export const fetchOrganizationById = (id: number): Promise<Organization> => apiFetch(`/organizations/${id}`);

export const updateOrganizationSubscription = (organizationId: number, isSubscribed: boolean): Promise<Organization> => {
  return apiFetch(`/organizations/${organizationId}/subscription`, {
    method: 'POST',
    body: JSON.stringify({isSubscribed}),
  });
};

export const fetchOrganizationEvents = (): Promise<OrganizationEvent[]> => apiFetch(`/organization/events`);
export const fetchEventParticipants = (eventId: number): Promise<EventParticipant[]> => apiFetch(`/organization/events/${eventId}/participants`);

export const fetchOrganizationDashboardStats = (): Promise<OrganizationStat[]> => apiFetch(`/organization/dashboard/stats`);
export const fetchOrganizationDetails = (): Promise<OrganizationDetails> => apiFetch(`/organization/details`);

export const fetchActivityHistoryEvents = async (): Promise<HistoryEvent[]> => {
  const data = await apiFetch<{ upcoming: any[], past: any[] }>('/profile/me/events');
  const upcoming = data.upcoming.map(event => ({...mapEventData(event), status: 'upcoming' as const}));
  const past = data.past.map(event => ({...mapEventData(event), status: 'past' as const}));
  return [...upcoming, ...past];
};

export const fetchLeaderboardData = (period: 'week' | 'month' | 'allTime'): Promise<LeaderboardUser[]> => apiFetch(`/leaderboard?period=${period}`);

export const fetchAllAchievements = async (): Promise<Achievement[]> => {
  const achievements = await apiFetch<(Omit<Achievement, 'Icon'> & { icon?: string | null })[]>('/achievements');
  return achievements.map(mapIcon);
};

export const fetchMyChats = async (): Promise<MyChatItem[]> => {
  const chats = await apiFetch<any[]>('/profile/chats');
  return chats.map(chat => ({...chat, Icon: getIconForCategory(chat.category)}));
};

export const fetchAllStories = (): Promise<Story[]> => apiFetch('/stories');
export const fetchStoryById = (id: number): Promise<Story> => apiFetch(`/stories/${id}`);

export const fetchRewards = (): Promise<RewardItem[]> => apiFetch('/rewards');

export const fetchMapMarkers = (): Promise<MapMarker[]> => apiFetch('/map-markers');

export const fetchFriends = (): Promise<Friend[]> => apiFetch('/friends');
export const fetchEventChatMessages = (eventId: number): Promise<EventChatMessage[]> => apiFetch(`/events/${eventId}/messages`);

export const fetchWeeklyChallenge = async (): Promise<WeeklyChallenge> => {
  const challenge = await apiFetch<Omit<WeeklyChallenge, 'Icon'> & { icon?: string | null }>('/challenge/weekly');
  return mapIcon(challenge);
};

